class Solution:
    def peaksInArray(self, nums, queries):
        n = len(nums)
        c = [0] * (4 * n); s1 = [0] * (4 * n); s2 = [0] * (4 * n)

        def upd(node, l, r, p, a, b, d):
            if l == r:
                c[node] += a; s1[node] += b; s2[node] += d
                return
            m = (l + r) // 2
            if p <= m: upd(2 * node, l, m, p, a, b, d)
            else: upd(2 * node + 1, m + 1, r, p, a, b, d)
            c[node] = c[2 * node] + c[2 * node + 1]
            s1[node] = s1[2 * node] + s1[2 * node + 1]
            s2[node] = s2[2 * node] + s2[2 * node + 1]

        def qry(node, l, r, ql, qr):
            if qr < l or r < ql: return (0, 0, 0)
            if ql <= l and r <= qr: return (c[node], s1[node], s2[node])
            m = (l + r) // 2
            A = qry(2 * node, l, m, ql, qr)
            B = qry(2 * node + 1, m + 1, r, ql, qr)
            return (A[0] + B[0], A[1] + B[1], A[2] + B[2])

        def isPeak(i):
            return 0 < i < n - 1 and nums[i] > nums[i - 1] and nums[i] > nums[i + 1]

        for i in range(n):
            if isPeak(i):
                upd(1, 0, n - 1, i, 1, i, i * i)

        res = []
        for q in queries:
            if q[0] == 1:
                l, r = q[1], q[2]
                if l + 1 > r - 1:
                    res.append(0)
                    continue
                cc, t1, t2 = qry(1, 0, n - 1, l + 1, r - 1)
                res.append((l + r) * t1 - t2 - l * r * cc)
            else:
                idx, v = q[1], q[2]
                for j in (idx - 1, idx, idx + 1):
                    if isPeak(j):
                        upd(1, 0, n - 1, j, -1, -j, -j * j)
                nums[idx] = v
                for j in (idx - 1, idx, idx + 1):
                    if isPeak(j):
                        upd(1, 0, n - 1, j, 1, j, j * j)
        return res

