class Solution {
    int n;
    vector<long long> c, s1, s2, a;
    void pull(int nd){ c[nd]=c[2*nd]+c[2*nd+1]; s1[nd]=s1[2*nd]+s1[2*nd+1]; s2[nd]=s2[2*nd]+s2[2*nd+1]; }
    void upd(int nd,int l,int r,int p,long long x,long long y,long long z){
        if(l==r){ c[nd]+=x; s1[nd]+=y; s2[nd]+=z; return; }
        int m=(l+r)/2;
        if(p<=m) upd(2*nd,l,m,p,x,y,z); else upd(2*nd+1,m+1,r,p,x,y,z);
        pull(nd);
    }
    array<long long,3> qry(int nd,int l,int r,int ql,int qr){
        if(qr<l||r<ql) return {0,0,0};
        if(ql<=l&&r<=qr) return {c[nd],s1[nd],s2[nd]};
        int m=(l+r)/2;
        auto A=qry(2*nd,l,m,ql,qr), B=qry(2*nd+1,m+1,r,ql,qr);
        return {A[0]+B[0],A[1]+B[1],A[2]+B[2]};
    }
    bool isPeak(int i){ return i>0 && i<n-1 && a[i]>a[i-1] && a[i]>a[i+1]; }
public:
    vector<long long> peaksInArray(vector<int>& nums, vector<vector<int>>& queries) {
        n=nums.size(); a.assign(nums.begin(),nums.end());
        c.assign(4*n,0); s1.assign(4*n,0); s2.assign(4*n,0);
        for(int i=0;i<n;i++) if(isPeak(i)) upd(1,0,n-1,i,1,i,(long long)i*i);
        vector<long long> res;
        for(auto& q:queries){
            if(q[0]==1){
                long long l=q[1], r=q[2];
                if(l+1>r-1){ res.push_back(0); continue; }
                auto t=qry(1,0,n-1,l+1,r-1);
                res.push_back((l+r)*t[1]-t[2]-l*r*t[0]);
            } else {
                int idx=q[1], v=q[2];
                for(int j=idx-1;j<=idx+1;j++) if(isPeak(j)) upd(1,0,n-1,j,-1,-j,-(long long)j*j);
                a[idx]=v;
                for(int j=idx-1;j<=idx+1;j++) if(isPeak(j)) upd(1,0,n-1,j,1,j,(long long)j*j);
            }
        }
        return res;
    }
};

