var peaksInArray = function(nums, queries) {
    const n = nums.length;
    const a = nums.slice();
    const SZ = 4 * n;
    const c = new Array(SZ).fill(0), s1 = new Array(SZ).fill(0), s2 = new Array(SZ).fill(0);
    const pull = nd => { c[nd]=c[2*nd]+c[2*nd+1]; s1[nd]=s1[2*nd]+s1[2*nd+1]; s2[nd]=s2[2*nd]+s2[2*nd+1]; };
    function upd(nd, l, r, p, x, y, z) {
        if (l === r) { c[nd]+=x; s1[nd]+=y; s2[nd]+=z; return; }
        const m = (l + r) >> 1;
        if (p <= m) upd(2*nd, l, m, p, x, y, z); else upd(2*nd+1, m+1, r, p, x, y, z);
        pull(nd);
    }
    function qry(nd, l, r, ql, qr) {
        if (qr < l || r < ql) return [0, 0, 0];
        if (ql <= l && r <= qr) return [c[nd], s1[nd], s2[nd]];
        const m = (l + r) >> 1;
        const A = qry(2*nd, l, m, ql, qr), B = qry(2*nd+1, m+1, r, ql, qr);
        return [A[0]+B[0], A[1]+B[1], A[2]+B[2]];
    }
    const isPeak = i => i > 0 && i < n - 1 && a[i] > a[i-1] && a[i] > a[i+1];
    for (let i = 0; i < n; i++) if (isPeak(i)) upd(1, 0, n - 1, i, 1, i, BigInt(i) * BigInt(i));
    const res = [];
    for (const q of queries) {
        if (q[0] === 1) {
            const l = q[1], r = q[2];
            if (l + 1 > r - 1) { res.push(0); continue; }
            const t = qry(1, 0, n - 1, l + 1, r - 1);
            res.push(Number(BigInt(l + r) * t[1] - t[2] - BigInt(l) * BigInt(r) * t[0]));
        } else {
            const idx = q[1], v = q[2];
            for (let j = idx - 1; j <= idx + 1; j++) if (isPeak(j)) upd(1, 0, n - 1, j, -1, -BigInt(j), -(BigInt(j) * BigInt(j)));
            a[idx] = v;
            for (let j = idx - 1; j <= idx + 1; j++) if (isPeak(j)) upd(1, 0, n - 1, j, 1, BigInt(j), BigInt(j) * BigInt(j));
        }
    }
    return res;
};
